// Check if AI Agent had an error (token exhausted, rate limit, etc.)
const agentOutput = $input.first().json;
const inputData = $('Parse Request Data').first().json;

// Check for errors in the agent output
const hasError = agentOutput.error || 
                 agentOutput.$error || 
                 !agentOutput.output ||
                 (typeof agentOutput.output === 'string' && agentOutput.output.includes('rate limit'));

// Check for token/quota errors in error message
const isTokenError = hasError && (
  (agentOutput.error && typeof agentOutput.error === 'string' && (
    agentOutput.error.toLowerCase().includes('quota') ||
    agentOutput.error.toLowerCase().includes('token') ||
    agentOutput.error.toLowerCase().includes('rate limit') ||
    agentOutput.error.toLowerCase().includes('insufficient') ||
    agentOutput.error.toLowerCase().includes('exceeded') ||
    agentOutput.error.toLowerCase().includes('billing')
  )) ||
  (agentOutput.$error && typeof agentOutput.$error.message === 'string' && (
    agentOutput.$error.message.toLowerCase().includes('quota') ||
    agentOutput.$error.message.toLowerCase().includes('token') ||
    agentOutput.$error.message.toLowerCase().includes('rate limit') ||
    agentOutput.$error.message.toLowerCase().includes('insufficient') ||
    agentOutput.$error.message.toLowerCase().includes('exceeded') ||
    agentOutput.$error.message.toLowerCase().includes('billing')
  ))
);

if (hasError) {
  // Return fallback signal to Vercel
  return [
    {
      json: {
        fallback: true,
        useFallback: true,
        reason: isTokenError ? 'token_exhausted' : 'ai_error',
        errorDetails: agentOutput.error || agentOutput.$error?.message || 'Unknown error',
        sessionId: inputData.sessionId,
        timestamp: new Date().toISOString()
      }
    }
  ];
}

// Success - return sanitized response
return [
  {
    json: {
      sessionId: inputData.sessionId,
      userMessage: inputData.message,
      aiResponse: agentOutput.output || agentOutput.text || '',
      timestamp: new Date().toISOString(),
      fallback: false
    }
  }
];
